old='''export async function acceptStockTransfer(transferId: string) {\n  return dataRequest<{transfer_id:string;status:string;relationship_type:"same_owner"|"commercial";total_amount:number;invoice_id:string|null;charge_id:number|null}>("rpc/accept_stock_transfer", { method:"POST", body:JSON.stringify({ p_transfer_id:transferId,p_idempotency_key:crypto.randomUUID() }) });\n}'''
new='''export async function acceptStockTransfer(transferId: string, mappings: Array<{transferLineId:number;destinationProductId?:number;createNew?:boolean}> = []) {\n  return dataRequest<{transfer_id:string;status:string;relationship_type:"same_owner"|"commercial";total_amount:number;invoice_id:string|null;charge_id:number|null;supplier_id?:number|null}>("rpc/accept_stock_transfer", { method:"POST", body:JSON.stringify({ p_transfer_id:transferId,p_idempotency_key:crypto.randomUUID(),p_line_mappings:mappings.map(mapping=>({transfer_line_id:mapping.transferLineId,destination_product_id:mapping.destinationProductId ?? null,create_new:mapping.createNew === true})) }) });\n}'''
assert old in s
s=s.replace(old,new)
api.write_text(s)

